<template>
  <div id="booking">
    <v-carousel height="100vh" hide-controls dark hide-delimiters class="myCarousel">
      <v-carousel-item
        v-for="(item,i) in carouselitems"
        :key="i"
        :src="item.src"
        class="carouselItem"
      ></v-carousel-item>
      <v-jumbotron dark class="myJumbotron">
        <v-container fill-height>
          <v-layout align-center>
            <v-flex class="showcaseText">
              <h2 class="text-lg-center text-md-center text-xs-center myHeading">Booking</h2>
              <p
                class="subheading text-lg-center text-md-center text-xs-center mygreenText"
              >Hospitality Unparalled</p>
            </v-flex>
          </v-layout>
        </v-container>
      </v-jumbotron>
    </v-carousel>
    <v-layout class="section">
      <v-card min-width="80vw" class="mx-auto mt-2 mb-2" justify-center>
        <v-card-text class="text-lg-center text-md-center text-sm-center">Book with us</v-card-text>
        <div class="form-body">
          <form>
            <v-text-field
              v-model="Name"
              :error-messages="nameErrors"
              :counter="10"
              label="Name"
              required
              @input="$v.name.$touch()"
              @blur="$v.name.$touch()"
            ></v-text-field>
            <v-text-field
              v-model="number"
              :counter="10"
              label="Phone Number"
              required
              @input="$v.name.$touch()"
              @blur="$v.name.$touch()"
            ></v-text-field>
            <v-text-field
              v-model="Email"
              :error-messages="emailErrors"
              label="E-mail"
              required
              @input="$v.email.$touch()"
              @blur="$v.email.$touch()"
            ></v-text-field>
            <v-select
              v-model="services"
              :items="Services"
              :error-messages="selectErrors"
              label="Services"
              @change="$v.select.$touch()"
              @blur="$v.select.$touch()"
            ></v-select>
            <v-layout v-if="services == 'Accomodation'" row wrap>
              <v-flex lg8>
                <v-select
                  v-model="accomodation"
                  :items="Accomodation"
                  label="Accomodations"
                  @change="$v.select.$touch()"
                  @blur="$v.select.$touch()"
                ></v-select>
              </v-flex>
              <v-flex lg4>
                <v-text-field
                  v-model="guestnumber"
                  label="Number of people"
                  required
                  @input="$v.name.$touch()"
                  @blur="$v.name.$touch()"
                ></v-text-field>
              </v-flex>
            </v-layout>
            <v-layout v-if="services == 'Conferences'" row wrap>
              <v-flex lg8>
                <v-select
                  v-model="conferences"
                  :items="Conferences"
                  label="Conference"
                  @change="$v.select.$touch()"
                  @blur="$v.select.$touch()"
                ></v-select>
              </v-flex>
              <v-flex lg4>
                <v-text-field
                  v-model="guestnumber"
                  label="Number of people"
                  required
                  @input="$v.name.$touch()"
                  @blur="$v.name.$touch()"
                ></v-text-field>
              </v-flex>
            </v-layout>
            <v-layout row wrap>
              <v-flex xs12 sm6 md4>
                <v-dialog
                  ref="dialog"
                  v-model="modal"
                  :return-value.sync="date"
                  persistent
                  lazy
                  full-width
                  width="290px"
                >
                  <template v-slot:activator="{ on }">
                    <v-text-field
                      v-model="date"
                      label="Arrival Date"
                      prepend-icon="event"
                      readonly
                      v-on="on"
                    ></v-text-field>
                  </template>
                  <v-date-picker v-model="date" scrollable>
                    <v-spacer></v-spacer>
                    <v-btn flat color="brown" @click="modal = false">Cancel</v-btn>
                    <v-btn flat color="green" @click="$refs.dialog.save(date)">OK</v-btn>
                  </v-date-picker>
                </v-dialog>
              </v-flex>
              <v-spacer></v-spacer>
              <v-flex xs12 sm6 md4></v-flex>
              <v-flex xs12 sm6 md4>
                <v-dialog
                  ref="dialog"
                  v-model="modal2"
                  :return-value.sync="date"
                  persistent
                  lazy
                  full-width
                  width="290px"
                >
                  <template v-slot:activator="{ on }">
                    <v-text-field
                      v-model="deptdate"
                      label="Departure Date"
                      prepend-icon="event"
                      readonly
                      v-on="on"
                    ></v-text-field>
                  </template>
                  <v-date-picker v-model="date" scrollable>
                    <v-spacer></v-spacer>
                    <v-btn flat color="brown" @click="modal2 = false">Cancel</v-btn>
                    <v-btn flat color="green" @click="$refs.dialog.save(date)">OK</v-btn>
                  </v-date-picker>
                </v-dialog>
              </v-flex>
              <v-spacer></v-spacer>
            </v-layout>

            <v-checkbox
              v-model="checkbox"
              :error-messages="checkboxErrors"
              label="Free WiFI"
              required
              @change="$v.checkbox.$touch()"
              @blur="$v.checkbox.$touch()"
            ></v-checkbox>
            <v-layout row wrap justify-space-around>
              <v-btn color="#2cc804" @click="submit">submit</v-btn>
              <v-btn color="#531503" @click="clear">clear</v-btn>
            </v-layout>
          </form>
        </div>
      </v-card>
    </v-layout>
  </div>
</template>
<script>
import { validationMixin } from "vuelidate";
import { required, maxLength, email } from "vuelidate/lib/validators";

export default {
  name: "Booking",
  mixins: [validationMixin],

  validations: {
    name: { required, maxLength: maxLength(10) },
    email: { required, email },
    select: {},
    checkbox: {
      checked(val) {
        return val;
      }
    }
  },

  data: () => ({
    name: "",
    number: "",
    email: "",
    service: null,
    accomodation: null,
    conference: null,
    guestnumber: "",
    Services: ["Accomodation", "Conferences"],
    Accomodation: ["Single Room", "Deluxe Rooms", "Family Rooms", "Suite"],
    Conferences: ["Mami BoardRoom", "Baraza Hall"],
    checkbox: false,
    date: new Date().toISOString().substr(0, 10),
    deptdate: new Date().toISOString().substr(0, 10),
    modal: false,
    modal2: false,
    carouselitems: [
      {
        src: require("../assets/images/grounds/imageY.jpg")
      },
      {
        src: require("../assets/images/grounds/imageG.jpg")
      },
      {
        src: require("../assets/images/grounds/imageO.jpg")
      }
    ]
  }),

  computed: {
    checkboxErrors() {
      const errors = [];
      if (!this.$v.checkbox.$dirty) return errors;
      !this.$v.checkbox.checked && errors.push("You must agree to continue!");
      return errors;
    },
    selectErrors() {
      const errors = [];
      if (!this.$v.select.$dirty) return errors;
      !this.$v.select.required && errors.push("Item is required");
      return errors;
    },
    nameErrors() {
      const errors = [];
      if (!this.$v.name.$dirty) return errors;
      !this.$v.name.maxLength &&
        errors.push("Name must be at most 10 characters long");
      !this.$v.name.required && errors.push("Name is required.");
      return errors;
    },
    emailErrors() {
      const errors = [];
      if (!this.$v.email.$dirty) return errors;
      !this.$v.email.email && errors.push("Must be valid e-mail");
      !this.$v.email.required && errors.push("E-mail is required");
      return errors;
    }
  },

  methods: {
    submit() {
      this.$v.$touch();
    },
    clear() {
      this.$v.$reset();
      this.name = "";
      this.email = "";
      this.service = null;
      this.accomodation = null;
      this.conference = null;
      this.checkbox = false;
    }
  }
};
</script>
<style>
@import "../assets/css/style.css";
.form-body {
  width: 80%;
  margin: 1em auto;
}
</style>
